function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof JAIPUR_INFO&&(n.innerHTML=JAIPUR_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_DATA&&(n.innerHTML=TIMELINE_DATA.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderRulers(){const n=document.getElementById("rulers-grid");n&&"undefined"!=typeof RULERS_DATA&&(n.innerHTML=RULERS_DATA.map(n=>`\n        <div class="ruler-card">\n            <h3>👑 ${n.name}</h3>\n            <span class="ruler-role">${n.role}</span>\n            <p>${n.achievements}</p>\n        </div>\n    `).join(""))}function renderContributions(){if("undefined"==typeof CONTRIBUTIONS_DATA)return;const n=document.getElementById("contrib-overview"),e=document.getElementById("contrib-plan"),t=document.getElementById("contrib-astro"),r=document.getElementById("contrib-forts"),i=document.getElementById("contrib-crafts");n&&(n.innerHTML=`<strong>Overview:</strong> ${CONTRIBUTIONS_DATA.overview}`),e&&(e.innerHTML=`<strong>Grid-Planned City Architecture:</strong> ${CONTRIBUTIONS_DATA.plannedCityDesign}`),t&&(t.innerHTML=`<strong>Astronomical Jantar Mantar:</strong> ${CONTRIBUTIONS_DATA.astronomyJantarMantar}`),r&&(r.innerHTML=`<strong>Forts & Palaces:</strong> ${CONTRIBUTIONS_DATA.architectureForts}`),i&&(i.innerHTML=`<strong>Arts & Craft Guilds:</strong> ${CONTRIBUTIONS_DATA.handicraftsArts}`)}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTimeline(),renderRulers(),renderContributions(),renderGallery(),renderReferences(),initThemeToggle()});